def calculate_power_law_bottom_probability(data, bottom_window_days=30):
  """Retient les creux de marché significatifs selon la Power Law."""
  required_columns = {"Close", "z_score_pl"}
  if data.empty or not required_columns.issubset(data.columns):
    return None

  prices = pd.to_numeric(data["Close"], errors="coerce").to_numpy(dtype=float)
  z_scores = pd.to_numeric(data["z_score_pl"], errors="coerce").to_numpy(dtype=float)
  valid = np.isfinite(prices) & (prices > 0) & np.isfinite(z_scores)
  if valid.sum() < 365:
    return None

  log_prices = np.log(prices[valid])
  valid_z_scores = z_scores[valid]
  valid_dates = pd.to_datetime(data.loc[valid, "Date"]).to_numpy()
  candidate_indices, _ = find_peaks(-log_prices, distance=120, prominence=np.log(1.30))
  bottom_indices = np.array([
      index for index in candidate_indices
      if index >= 365 and index + 365 < len(log_prices)
      and valid_z_scores[index] <= -0.85
      and 1.0 - np.exp(log_prices[index] - np.max(log_prices[index - 365 : index + 1])) >= 0.45
      and np.exp(np.max(log_prices[index + 1 : index + 366]) - log_prices[index]) - 1.0 >= 0.50
  ], dtype=int)
  if len(bottom_indices) == 0:
    return None

  bottom_zone = np.zeros(len(log_prices), dtype=bool)
  for index in bottom_indices:
    start = max(0, index - int(bottom_window_days))
    end = min(len(bottom_zone), index + int(bottom_window_days) + 1)
    bottom_zone[start:end] = True

  current_z = float(valid_z_scores[-1])
  bandwidth = max(0.35, float(np.nanstd(valid_z_scores)) * 0.18)
  weights = np.exp(-0.5 * ((valid_z_scores - current_z) / bandwidth) ** 2)
  base_rate = float(bottom_zone.mean())
  probability = float((np.dot(weights, bottom_zone) + 30 * base_rate) / (weights.sum() + 30))
  bottom_z_scores = valid_z_scores[bottom_indices]
  return {
      "probability": probability,
      "base_rate": base_rate,
      "current_z": current_z,
      "bottom_count": int(len(bottom_indices)),
      "bottom_z_median": float(np.median(bottom_z_scores)),
      "bottom_dates": valid_dates[bottom_indices],
      "bottom_z_scores": bottom_z_scores,
  }


@st.cache_data(ttl=3600, max_entries=2, show_spinner=False)
def load_mstr_data():
  """Charge les clôtures ajustées de Strategy (MSTR) depuis Yahoo Finance."""
  try:
    import yfinance as yf
    raw = yf.download("MSTR", start="2020-01-01", auto_adjust=True, progress=False)
    if raw.empty:
      return pd.DataFrame(columns=["Date", "Close"])
    if isinstance(raw.columns, pd.MultiIndex):
      raw.columns = raw.columns.get_level_values(0)
    data = raw.reset_index()[["Date", "Close"]].dropna()
    data["Date"] = pd.to_datetime(data["Date"]).dt.tz_localize(None)
    return data.loc[data["Close"] > 0].reset_index(drop=True)
  except Exception:
    return pd.DataFrame(columns=["Date", "Close"])


@st.cache_data(max_entries=12, show_spinner=False)
def fit_mstr_log_periodic_model(mstr_data, start_date):
  """Ajuste une Power Law et une LPPL harmonique sur l'historique MSTR."""
  data = mstr_data.loc[pd.to_datetime(mstr_data["Date"]) >= pd.Timestamp(start_date)].copy()
  data = data.dropna(subset=["Close"]).reset_index(drop=True)
  if len(data) < 180:
    return pd.DataFrame(), {}
  days = np.arange(1, len(data) + 1, dtype=float)
  log_time = np.log(days)
  log_price = np.log(data["Close"].to_numpy(dtype=float))
  trend_design = np.column_stack([np.ones(len(data)), log_time])
  trend_coef, *_ = np.linalg.lstsq(trend_design, log_price, rcond=None)
  trend_log = trend_design @ trend_coef
  best_fit = None
  for omega in np.linspace(2.0, 16.0, 71):
    design = np.column_stack([
        np.ones(len(data)), log_time,
        np.cos(omega * log_time), np.sin(omega * log_time),
        np.cos(2.0 * omega * log_time), np.sin(2.0 * omega * log_time),
    ])
    coef, *_ = np.linalg.lstsq(design, log_price, rcond=None)
    fitted = design @ coef
    mse = float(np.mean((log_price - fitted) ** 2))
    if best_fit is None or mse < best_fit[0]:
      best_fit = (mse, omega, fitted, coef)
  mse, omega, lppl_log, lppl_coef = best_fit
  residuals = log_price - trend_log
  residual_std = float(np.std(residuals))
  data["trend_price"] = np.exp(trend_log)
  data["lppl_price"] = np.exp(lppl_log)
  data["z_score_pl"] = residuals / residual_std if residual_std > 0 else 0.0
  data["upper_band"] = np.exp(trend_log + 2.0 * residual_std)
  data["lower_band"] = np.exp(trend_log - 2.0 * residual_std)
  r_squared = 1.0 - float(np.sum((log_price - lppl_log) ** 2) / np.sum((log_price - log_price.mean()) ** 2))
  return data, {
      "omega": float(omega), "r_squared": r_squared, "sigma": residual_std,
      "trend_coefficients": trend_coef.tolist(), "lppl_coefficients": lppl_coef.tolist(),
  }


class _HiddenCloudSection:
  """Conserve les calculs locaux sans exposer de vue Expert sur Cloud."""

  def __init__(self):
    self._slot = st.empty()
    self._container = self._slot.container()

  def __enter__(self):
    return self._container.__enter__()

  def __exit__(self, exc_type, exc_value, traceback):
    self._container.__exit__(exc_type, exc_value, traceback)
    self._slot.empty()

