@st.cache_data(ttl=21600, max_entries=4, show_spinner=False)
def load_market_comparison_assets(start_date, end_date):
  """Charge les clôtures des actifs comparés via Yahoo Finance."""
  import yfinance as yf

  assets = {
      "Brent": "BZ=F",
      "Or": "GC=F",
      "Nasdaq": "^IXIC",
      "MSTR": "MSTR",
      "S&P 500": "^GSPC",
      "Euro": "EURUSD=X",
      "Ethereum": "ETH-USD",
      "Solana": "SOL-USD",
      "XRP": "XRP-USD",
  }
  series_by_asset = {}
  for label, ticker in assets.items():
    try:
      raw = yf.download(
          ticker,
          start=pd.Timestamp(start_date).strftime("%Y-%m-%d"),
          end=(pd.Timestamp(end_date) + timedelta(days=1)).strftime("%Y-%m-%d"),
          auto_adjust=True,
          progress=False,
          threads=False,
      )
      if raw.empty or "Close" not in raw:
        continue
      close = raw["Close"]
      if isinstance(close, pd.DataFrame):
        close = close.iloc[:, 0]
      close.index = pd.DatetimeIndex(close.index).tz_localize(None)
      series_by_asset[label] = pd.to_numeric(close, errors="coerce").dropna()
    except Exception:
      continue
  return pd.DataFrame(series_by_asset)


